from pathlib import Path
import subprocess,json,hashlib,datetime
root=Path('/workspace/room7-freight-circulation-native');repo=Path('/workspace/containment-room7');m=json.loads((root/'manifest.json').read_text());hashfile=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
current=[{'path':r['path'],'sha256':hashfile(repo/r['path'])}for r in m['sourceBefore']['files']];assert current==m['sourceBefore']['files'];head=subprocess.check_output(['git','-C',str(repo),'rev-parse','HEAD'],text=True).strip();assert head==m['sourceBefore']['commit'];status=subprocess.check_output(['git','-C',str(repo),'status','--porcelain','--','src','public','scripts','tests','package.json','package-lock.json','vite.config.ts'],text=True);assert status==''
frames=sorted((root/'frames').glob('*.png'));assert len(frames)==len(m['frames'])==415
video=root/'failed-circulation-with-encounter-clear.mp4';cmd=['ffmpeg','-hide_banner','-loglevel','error','-y','-framerate','20','-i',str(root/'frames/%05d.png'),'-c:v','libx264','-pix_fmt','yuv420p','-movflags','+faststart',str(video)];subprocess.run(cmd,check=True);subprocess.run(['ffmpeg','-v','error','-i',str(video),'-f','null','-'],check=True);probe=json.loads(subprocess.check_output(['ffprobe','-v','error','-count_frames','-show_streams','-show_format','-of','json',str(video)]));assert int(probe['streams'][0]['nb_read_frames'])==415
out={'recordedAt':datetime.datetime.now(datetime.timezone.utc).isoformat(),'disclosure':'Original FAILED manifest unchanged: ordinary encounter cleared at415frames but waypoint controller oscillated near southwest corner and did not complete the eight-waypoint circulation. No complete circulation claim. Four-frame decisions can leap over the20-unit arrival radius at220units/second; a separate corrected recorder will use two-frame decisions without changing game simulation or tolerance. Video encoded after failure from all415retainedframes; source check is separate, not a retroactive sourceAfter field.','manifestSha256':hashfile(root/'manifest.json'),'sourceAfterFailure':{'commit':head,'status':status,'files':current},'command':cmd,'video':{'file':video.name,'sha256':hashfile(video),'probe':probe},'frames':[{'file':str(p.relative_to(root)),'sha256':hashfile(p)}for p in frames]};(root/'postfailure-provenance.json').write_text(json.dumps(out,indent=2)+'\n');print('Preserved',len(frames),'frames',out['video']['sha256'])
